(function ($) {
	"use strict";

	// Guard to prevent double execution of global listeners
	if (window.milaknightFunctionsInitialized) return;
	window.milaknightFunctionsInitialized = true;

	document.addEventListener("DOMContentLoaded", function () {
		document.querySelectorAll("img").forEach((img, index) => {
			if (index >= 10) {
				img.setAttribute("loading", "lazy");
			} else {
				img.removeAttribute("loading");
			}
		});
	});


	document.addEventListener('DOMContentLoaded', function () {
		if (window.milaknightProjectNavInitialized) return;
		window.milaknightProjectNavInitialized = true;

		const navLinks = document.querySelectorAll('.our-Project-nav a');
		const postContainers = Array.from(document.querySelectorAll('.col-lg-4, .col-md-6'));

		function normalizeFilterValue(raw) {
			if (!raw) return '*';
			raw = raw.trim();
			if (raw === '*') return '*';
			return raw.startsWith('.') ? raw.slice(1) : raw;
		}

		function applyFilter(filterRaw) {
			const filter = normalizeFilterValue(filterRaw);

			postContainers.forEach(container => {
				if (!container.querySelector('.post-item')) return;

				if (filter === '*' || container.classList.contains(filter)) {

					container.classList.remove('post-hidden');
				} else {

					container.classList.add('post-hidden');
				}
			});
		}
		navLinks.forEach(link => {
			link.setAttribute('role', 'button');

			link.addEventListener('click', function (e) {
				e.preventDefault();
				const filter = this.getAttribute('data-filter') || '*';
				navLinks.forEach(l => l.classList.remove('active-btn'));
				this.classList.add('active-btn');
				applyFilter(filter);
			});


			link.addEventListener('keydown', function (e) {
				if (e.key === 'Enter' || e.key === ' ') {
					e.preventDefault();
					this.click();
				}
			});
		});
		const defaultActive = document.querySelector('.our-Project-nav a.active-btn');
		if (defaultActive) {
			applyFilter(defaultActive.getAttribute('data-filter'));
		} else {
			applyFilter('*');
		}
	});


	/* testimonial Slider JS */
	if ($('.testimonial-slider').length && !$('.testimonial-slider .swiper-initialized').length) {
		const testimonial_slider = new Swiper('.testimonial-slider .swiper', {
			slidesPerView: 1,
			speed: 1000,
			spaceBetween: 60,
			loop: true,
			autoplay: {
				delay: 5000,
			},
			pagination: {
				el: '.testimonial-pagination',
				clickable: true,
			},
			navigation: {
				nextEl: '.testimonial-button-next',
				prevEl: '.testimonial-button-prev',
			},
			breakpoints: {
				768: {
					slidesPerView: 2,
				},
				991: {
					slidesPerView: 2,
				}
			}
		});
	}

	/* Agency Support Slider JS */
	if ($('.agency-supports-slider').length && !$('.agency-supports-slider .swiper-initialized').length) {
		const agency_supports_slider = new Swiper('.agency-supports-slider .swiper', {
			slidesPerView: 2,
			speed: 2000,
			spaceBetween: 30,
			loop: true,
			autoplay: {
				delay: 5000,
			},
			breakpoints: {
				768: {
					slidesPerView: 4,
				},
				991: {
					slidesPerView: 6,
				}
			}
		});
	}


	$(window).on("scroll", function () { if ($(this).scrollTop() > 0) { $("header").addClass("active"); } else { $("header").removeClass("active"); } }); var $window = $(window); var $body = $('body'); $window.on('load', function () { $(".preloader").fadeOut(600); }); if ($('.active-sticky-header').length) {
		$window.on('resize', function () { setHeaderHeight(); }); function setHeaderHeight() { $("header.main-header").css("height", $('header .header-sticky').outerHeight()); }
		$(window).on("scroll", function () {
			var fromTop = $(window).scrollTop(); setHeaderHeight(); var headerHeight = $('header .header-sticky').outerHeight()
			$("header .header-sticky").toggleClass("hide", (fromTop > headerHeight + 100)); $("header .header-sticky").toggleClass("active", (fromTop > 600));
		});
	}

	// SlickNav guard
	if ($('#menu').length && !$('.slicknav_menu').length) {
		$('#menu').slicknav({ label: '', prependTo: '.responsive-menu' });
	}

	if ($("a[href='#top']").length) {
		$("a[href='#top']").off('click').click(function () { $("html, body").animate({ scrollTop: 0 }, "slow"); return false; });
	}

	if ($('.typed-title').length && !$('.typed-title').data('typed')) {
		$('.typed-title').typed({ stringsElement: $('.typing-title'), backDelay: 2000, typeSpeed: 0, loop: true });
	}

	if ($('#herovideo').length && !$('#herovideo').hasClass('mb_YTPlayer')) {
		var myPlayer = $("#herovideo").YTPlayer();
	}

	if ($('.counter').length && !$('.counter').hasClass('counter-initialized')) {
		$('.counter').addClass('counter-initialized').counterUp({ delay: 6, time: 3000 });
	}

	if ($('.reveal').length) {
		gsap.registerPlugin(ScrollTrigger);
		let revealContainers = document.querySelectorAll(".reveal");
		revealContainers.forEach((container) => {
			if (container.classList.contains('reveal-initialized')) return;
			container.classList.add('reveal-initialized');
			let image = container.querySelector("img");
			let tl = gsap.timeline({ scrollTrigger: { trigger: container, toggleActions: "play none none none" } });
			tl.set(container, { autoAlpha: 1 });
			tl.from(container, 1, { xPercent: 0, ease: Power2.out });
			tl.from(image, 1, { xPercent: 100, scale: 1, delay: -1, ease: Power2.out });
		});
	}

	if ($('.text-anime-style-1').length) {
		let staggerAmount = 0.05, translateXValue = 0, delayValue = 0.5, animatedTextElements = document.querySelectorAll('.text-anime-style-1');
		animatedTextElements.forEach((element) => {
			if (element.classList.contains('split-text-initialized')) return;
			element.classList.add('split-text-initialized');
			let animationSplitText = new SplitText(element, { type: "chars, words" });
			gsap.from(animationSplitText.words, { duration: 1, delay: delayValue, x: 20, autoAlpha: 0, stagger: staggerAmount, scrollTrigger: { trigger: element, start: "top 85%" }, });
		});
	}

	if ($('.text-anime-style-2').length) {
		let staggerAmount = 0.03, translateXValue = 20, delayValue = 0.1, easeType = "power2.out", animatedTextElements = document.querySelectorAll('.text-anime-style-2');
		animatedTextElements.forEach((element) => {
			if (element.classList.contains('split-text-initialized')) return;
			element.classList.add('split-text-initialized');
			let animationSplitText = new SplitText(element, { type: "chars, words" });
			gsap.from(animationSplitText.chars, { duration: 1, delay: delayValue, x: translateXValue, autoAlpha: 0, stagger: staggerAmount, ease: easeType, scrollTrigger: { trigger: element, start: "top 85%" }, });
		});
	}

	if ($('.text-anime-style-3').length) {
		let animatedTextElements = document.querySelectorAll('.text-anime-style-3');
		animatedTextElements.forEach((element) => {
			if (element.animation) { element.animation.progress(1).kill(); element.split.revert(); }
			element.split = new SplitText(element, { type: "lines,words,chars", linesClass: "split-line", });
			gsap.set(element, { perspective: 400 });
			gsap.set(element.split.chars, { opacity: 0, x: "50", });
			element.animation = gsap.to(element.split.chars, { scrollTrigger: { trigger: element, start: "top 90%" }, x: "0", y: "0", rotateX: "0", opacity: 1, duration: 1, ease: Back.easeOut, stagger: 0.02, });
		});
	}

	var $parallaxie = $('.parallaxie');
	if ($parallaxie.length && ($window.width() > 991) && !$parallaxie.data('parallaxie-init')) {
		if ($window.width() > 768) {
			$parallaxie.data('parallaxie-init', true).parallaxie({ speed: 0.55, offset: 0, });
		}
	}

	if (!$('.gallery-items').data('magnific-init')) {
		$('.gallery-items').data('magnific-init', true).magnificPopup({ delegate: 'a', type: 'image', closeOnContentClick: false, closeBtnInside: false, mainClass: 'mfp-with-zoom', image: { verticalFit: true, }, gallery: { enabled: true }, zoom: { enabled: true, duration: 300, opener: function (element) { return element.find('img'); } } });
	}

	$window.on("load", function () {
		if ($(".project-item-boxes").length && !$(".project-item-boxes").data('isotope')) {
			var $menuitem = $(".project-item-boxes").isotope({ itemSelector: ".project-item-box", layoutMode: "masonry", masonry: { columnWidth: 1, } });
			var $menudisesnav = $(".our-Project-nav li a");
			$menudisesnav.off('click').on('click', function (e) { var filterValue = $(this).attr('data-filter'); $menuitem.isotope({ filter: filterValue }); $menudisesnav.removeClass("active-btn"); $(this).addClass("active-btn"); e.preventDefault(); });
			$menuitem.isotope({ filter: "*" });
		}
	});

	if ($('.popup-video').length && !$('.popup-video').data('magnific-init')) {
		$('.popup-video').data('magnific-init', true).magnificPopup({ type: 'iframe', mainClass: 'mfp-fade', removalDelay: 160, preloader: false, fixedContentPos: true });
	}

	if ($('.why-choose-content').length) { var element = $('.why-choose-content'); var items = element.find('.why-choose-item'); if (items.length) { items.off('mouseenter mouseleave').on({ mouseenter: function () { if ($(this).hasClass('active')) return; items.removeClass('active'); $(this).addClass('active'); }, mouseleave: function () { } }); } }
})(jQuery);